import {STORIES,createChoices,choose,nextChoice,hintChoices,loadChoices,saveChoices} from './choices-engine.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PIP='/prototypes/i3-family-landing/assets/pip.svg';
/** Original vector scenes stay crisp on tablets. The object actually changes
 * after a choice: data clears, a fan spins, air flows, or a new owner appears. */
export function storyArt(story,solved=false,wrong=false){
  const faces='<circle cx="-12" cy="12" r="3"/><circle cx="12" cy="12" r="3"/><path d="M-10 25q10 '+(solved?'12':'5')+' 20 0" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>';
  const devices={
    speaker:`<rect x="-42" y="-70" width="84" height="122" rx="20" fill="#bdb0eb"/><circle cy="-33" r="23" fill="#647095"/><circle cy="-33" r="12" fill="#273f52"/>${faces}`,
    fan:`<rect x="-12" y="3" width="24" height="62" rx="8" fill="#e0ab60"/><rect x="-51" y="55" width="102" height="13" rx="6" fill="#315b57"/><circle cy="-24" r="58" fill="#d4edeb" stroke="#315b57" stroke-width="5"/><g class="cc-fan-blades" style="transform-origin:0px -24px">${[0,120,240].map(a=>`<path transform="rotate(${a} 0 -24)" d="M0-24q-47-36-24-43 36-12 24 43" fill="#538d88"/>`).join('')}</g><circle cy="-24" r="9" fill="#f0bc63"/>`,
    tablet:`<rect x="-51" y="-83" width="102" height="143" rx="17" fill="#294a59"/><rect x="-43" y="-73" width="86" height="114" rx="10" fill="#daf1e9"/><g class="cc-files" fill="#db926c"><rect x="-29" y="-55" width="23" height="23" rx="5"/><rect x="7" y="-55" width="23" height="23" rx="5"/></g>${faces}<circle cy="50" r="4" fill="white"/>`,
    phone:`<rect x="-37" y="-80" width="74" height="142" rx="18" fill="#31586a"/><rect x="-30" y="-69" width="60" height="109" rx="10" fill="#d8ebf1"/>${faces}<path d="M-7 51h14" stroke="white" stroke-width="4" stroke-linecap="round"/>`,
    battery:`<rect x="-13" y="-65" width="26" height="12" rx="4" fill="#647481"/><path d="M-35-51q-28 52 0 101h70q28-50 0-101z" fill="#eaa86f" stroke="#774b3a" stroke-width="4"/><path d="M6-39-17 2h19L-5 34 23-12H4z" fill="#fff8d7"/>`,
    camera:`<path d="M-26-47h38l10 15h30v81H-58v-81h23z" fill="#d8ab73" stroke="#385551" stroke-width="4"/><circle cy="7" r="29" fill="#375958"/><circle cy="7" r="18" fill="#8bc8be"/><circle cx="38" cy="-16" r="5" fill="#fff"/>`,
    laptop:`<rect x="-67" y="-70" width="134" height="94" rx="12" fill="#35576a"/><rect x="-58" y="-61" width="116" height="75" rx="7" fill="#d5eeec"/>${faces}<path d="M-67 25h134l22 26H-89z" fill="#a9bcc7"/><path d="M-79 51H79" stroke="#35576a" stroke-width="6" stroke-linecap="round"/>`,
    radio:`<path d="M17-65 48-91" stroke="#456764" stroke-width="5"/><rect x="-61" y="-45" width="122" height="95" rx="20" fill="#dfac75"/><circle cx="-20" r="26" fill="#335e59"/><g fill="#b1d2ba">${[-10,0,10].map(y=>`<path d="M-34 ${y}h28" stroke="#b1d2ba" stroke-width="3"/>`).join('')}</g><rect x="18" y="-23" width="30" height="14" rx="4" fill="#f4f2d4"/><circle cx="34" cy="18" r="10" fill="#faf5df"/>`,
    kettle:`<path d="M35-36q57-5 29 55H40" stroke="#3f6f69" stroke-width="13" fill="none"/><path d="M-40-31-58-47-63-37-45-2" fill="#6bafa1"/><path d="M-25-54h48q14 20 20 96H-46q0-74 21-96" fill="#81bdb0"/><rect x="-22" y="-65" width="46" height="12" rx="6" fill="#355e58"/>${faces}`,
  };
  const words={share:'A new home',repair:story.id==='unknown'?'Find out first':'More useful life',clear:'Data cleared',ewaste:'Expert care',adult:'Adult help',care:'Room to breathe',plan:'A family plan'};
  return `<svg viewBox="0 0 640 330" role="img" aria-label="${esc(story.place)}: ${solved?esc(words[story.effect]):esc(story.clue)}" class="cc-art ${solved?'is-solved':''} ${wrong?'is-wrong':''} cc-effect-${story.effect}"><defs><linearGradient id="cc-sky" x2="0" y2="1"><stop stop-color="#e0f2ed"/><stop offset="1" stop-color="#f6f9ed"/></linearGradient></defs><rect width="640" height="330" rx="24" fill="url(#cc-sky)"/><circle cx="529" cy="63" r="31" fill="#f9dda0"/><path d="M0 261q140-58 275-9t365-11v89H0" fill="#cae0c5"/><rect x="55" y="46" width="120" height="111" rx="17" fill="#fff" opacity=".8"/><path d="M115 48v108M57 101h116" stroke="#b9d9d1" stroke-width="5"/><path d="M60 229v-46q19-20 39 0v46z" fill="#799f6c"/><path d="M79 227v-67" stroke="#3e6e51" stroke-width="4"/><ellipse cx="320" cy="290" rx="143" ry="16" fill="#3c74621a"/><path class="cc-desk" d="M197 251h246v17H197zm17 17h12v53h-12zm201 0h12v53h-12" fill="#ba936a"/><g class="cc-device" transform="translate(320 189)" color="#294d46">${devices[story.item]||devices.phone}</g><g class="cc-result-person" transform="translate(480 197)"><circle cy="-21" r="21" fill="#a87352"/><path d="M-28 57v-42q28-22 56 0v42" fill="#557bc0"/><circle cx="-7" cy="-23" r="2"/><circle cx="7" cy="-23" r="2"/><path d="M-7-13q7 6 14 0" stroke="#49352c" stroke-width="2" fill="none"/><path d="M-27 18-39 32-68 11" stroke="#a87352" stroke-width="11" stroke-linecap="round" fill="none"/></g><g class="cc-air" fill="none" stroke="#619eaa" stroke-width="4" stroke-linecap="round"><path d="M388 185q46 12 47-13t18-8"/><path d="M394 200q63 17 70-10"/><path d="M210 187q-38-22-36 7"/></g><g class="cc-expert"><rect x="418" y="189" width="169" height="88" rx="15" fill="#376b60"/><text x="502" y="220" text-anchor="middle" fill="white" font-size="15" font-weight="800">E-WASTE SERVICE</text><path d="m456 243 14-13 14 13m-14-13v26m32-19 11 19h-23m48-20v19h20" stroke="#cbe78f" stroke-width="4" fill="none" stroke-linecap="round"/></g><g class="cc-stop"><path d="m480 165 22 22v31l-22 22h-32l-22-22v-31l22-22z" fill="#c56348"/><text x="464" y="208" text-anchor="middle" fill="white" font-size="17" font-weight="900">STOP</text></g>${solved?`<g class="cc-result-label"><rect x="205" y="18" width="230" height="36" rx="18" fill="#265e4f"/><text x="320" y="42" fill="white" text-anchor="middle" font-size="17" font-weight="800">✓ ${esc(words[story.effect])}</text></g>`:''}${wrong?'<g class="cc-wrong-sign"><circle cx="404" cy="90" r="25" fill="#b34b44"/><path d="m394 80 20 20m0-20-20 20" stroke="white" stroke-width="6" stroke-linecap="round"/></g>':''}</svg>`;
}
export function mountChoices(host,{signal,storage,onAward=()=>{},route=''}={}){
  const doc=host.ownerDocument,win=doc.defaultView,controller=new win.AbortController();
  if(signal?.aborted)return()=>{};
  if(storage===undefined)try{storage=win.localStorage;}catch{storage=null;}
  let sessions=loadChoices(storage),state=sessions.at(-1)||createChoices(),feedback=null,paused=!!win.matchMedia?.('(prefers-reduced-motion: reduce)').matches,saved=true;
  const save=()=>{sessions=[...sessions.filter(s=>s.id!==state.id),state].slice(-20);saved=saveChoices(storage,sessions);};
  const top=()=>`<nav class="cc-top"><a href="#learn">← All games</a><span>CIRCULAR CHOICES</span><div><a href="#howto?game=choices">How to play</a><button data-cc-motion aria-pressed="${paused}">${paused?'Motion off':'Pause motion'}</button><a href="#parents?view=choices">For parents ↗</a></div></nav>`;
  function draw(){
    doc.body.classList.add('ff-game-mode');
    host.classList.toggle('cc-paused',paused);
    if(state.complete){finish();return;}
    const story=STORIES[state.index],atLimit=state.attempts.length>=120&&!state.solved;
    if(atLimit)feedback={correct:false,text:'This round has lots of tries. Start a fresh round to keep exploring. Your grown-up can still review these tries.'};
    // Reloading after a correct choice must retain its visible outcome and Next.
    if(state.solved&&!feedback)feedback={correct:true,text:story.options.find(o=>o.id===story.answer).reply,gain:0};
    host.innerHTML=`<section class="cc-page">${top()}<header class="cc-heading"><div><p class="cc-kicker">STORY ${state.index+1} OF ${STORIES.length} · ${esc(story.place)}</p><h1>${esc(story.title)}</h1></div><div class="cc-score">✦ ${state.points}<span>Sparks</span></div></header><div class="cc-progress" aria-label="${state.index} of 10 stories complete">${STORIES.map((_,i)=>`<i class="${i<state.index?'done':i===state.index?'current':''}"></i>`).join('')}</div><div class="cc-story"><div class="cc-picture">${storyArt(story,state.solved,feedback?.correct===false)}<p class="cc-caption">${esc(story.clue)}</p>${state.solved?'<div class="cc-sparks" aria-hidden="true">'+Array.from({length:10},(_,i)=>`<i style="--i:${i}">✦</i>`).join('')+'</div>':''}</div><section class="cc-decision" aria-labelledby="cc-question"><div class="cc-pip"><img src="${PIP}" width="64" height="64" alt="Pip"><p>Look at the story.<br>Choose what happens next.</p></div><h2 id="cc-question">${esc(story.question)}</h2><div class="cc-options">${story.options.map((o,i)=>`<button data-cc-answer="${o.id}" ${state.solved?'disabled':''} class="${state.solved&&o.id===story.answer?'is-correct':''}"><b>${state.solved&&o.id===story.answer?'✓':String.fromCharCode(65+i)}</b><span>${esc(o.label)}</span></button>`).join('')}</div><button class="cc-hint" data-cc-hint ${state.solved?'disabled':''}>Help me think</button></section></div><div class="cc-feedback ${feedback?.correct===true?'correct':feedback?.correct===false?'wrong':''}" role="status" aria-live="polite"><b aria-hidden="true">${feedback?.correct===true?'✓':feedback?.correct===false?'✕':'✦'}</b><div><strong>${atLimit?'Time for a fresh round.':feedback?.correct===true?(feedback.gain?'Nice thinking! +'+feedback.gain+' Sparks':'Nice thinking!'):feedback?.correct===false?'Not yet. Try another idea.':'Your choice makes a difference.'}</strong><p>${esc(feedback?.text||'Tap one answer. Watch what happens. There is no timer.')}</p></div>${state.solved?`<button class="cc-next" data-cc-next>${state.index===9?'My discoveries':'Next story'} →</button>`:''}${state.attempts.length>=120&&!state.solved?'<button class="cc-next" data-cc-restart>Start a fresh round</button>':''}</div><p class="cc-note">Pretend items here. Adult help for real appliances.${saved?'':' Your browser could not save this round.'}</p></section>`;
  }
  function finish(){host.innerHTML=`<section class="cc-page cc-finish">${top()}<div class="cc-finish-inner"><img src="${PIP}" width="120" height="120" alt="Happy Pip"><p class="cc-kicker">TEN STORIES · TEN USEFUL DISCOVERIES</p><h1>You helped things<br>find their next chapter.</h1><div class="cc-score">✦ ${state.points} Sparks</div><p><strong>${state.firstCorrect}/10</strong> right on the first try. You worked through all 10.</p><div class="cc-takeaways"><span>↗ Share what works</span><span>⚒ Ask about repair</span><span>↻ Find e-waste help</span><span>✋ Adult help first</span></div><p>Tell your grown-up: <strong>what could we do with a forgotten device at home?</strong></p><div class="cc-finish-actions"><a class="cc-next" href="#parents?view=choices">Our discoveries →</a><a href="#learn">Try another game</a><button data-cc-restart>Play again</button></div><p class="cc-note">${saved?'Your choices are saved in this browser. No account or name needed.':'This browser could not save your round. Show this result to your grown-up before leaving.'}</p></div></section>`;}
  function parents(){
    doc.body.classList.remove('ff-game-mode');
    host.innerHTML=`<section class="ff-parent-page"><a href="#parents">← All learning records</a><p class="cc-kicker">CIRCULAR CHOICES · FOR GROWN-UPS</p><h1>The thinking behind each choice</h1><p>Revisit a missed choice together. These are practice records, not a measure of ability. Saved only in this browser.</p>${sessions.length?sessions.slice().reverse().map(s=>`<details class="cc-record"><summary>${s.complete?'Finished':'In progress'} · ${s.firstCorrect} first-try answers · ${s.points} Sparks</summary>${STORIES.filter(q=>s.attempts.some(a=>a.storyId===q.id)||s.hints.includes(q.id)).map(q=>{const tries=s.attempts.filter(a=>a.storyId===q.id);return`<article><h3>${esc(q.title)}</h3><p>${esc(q.clue)}</p><ol>${tries.map(a=>`<li><strong>${a.correct?'✓ Correct':'✕ Tried'}:</strong> ${esc(q.options.find(o=>o.id===a.answer)?.label)}</li>`).join('')}</ol>${s.hints.includes(q.id)?'<p>Asked for a thinking hint.</p>':''}<p><strong>The idea:</strong> ${esc(q.lesson)}</p><p><strong>Talk together:</strong> ${esc(q.talk)}</p></article>`;}).join('')}</details>`).join(''):'<div class="cc-record"><h2>No stories played yet</h2><p>Each choice will appear here, including retries and hints.</p></div>'}<a class="cc-next" href="#learn?game=choices">Play Circular Choices →</a></section>`;
  }
  host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
    if(b.hasAttribute('data-cc-answer')){const result=choose(state,b.dataset.ccAnswer);if(!result.accepted)return;state=result.state;feedback=result;save();draw();host.querySelector(result.correct?'[data-cc-next]':`[data-cc-answer="${b.dataset.ccAnswer}"]`)?.focus({preventScroll:true});}
    if(b.hasAttribute('data-cc-next')){state=nextChoice(state);feedback=null;save();draw();host.querySelector('h1')?.setAttribute('tabindex','-1');host.querySelector('h1')?.focus({preventScroll:true});if(state.complete)onAward('circular-stories:'+state.id,state.points);}
    if(b.hasAttribute('data-cc-hint')){state=hintChoices(state);feedback={text:STORIES[state.index].lesson};save();draw();host.querySelector('[data-cc-hint]')?.focus({preventScroll:true});}
    if(b.hasAttribute('data-cc-motion')){paused=!paused;draw();host.querySelector('[data-cc-motion]')?.focus({preventScroll:true});}
    if(b.hasAttribute('data-cc-restart')){state=createChoices();feedback=null;save();draw();}
  },{signal:controller.signal});
  if(String(route).includes('parents'))parents();else{save();draw();}
  const cleanup=()=>{controller.abort();doc.body.classList.remove('ff-game-mode');host.classList.remove('cc-paused');};signal?.addEventListener('abort',cleanup,{once:true});return cleanup;
}
